import{z as A,x as B,o as l,c as d,q as n,j as t,D as e,d as o,s as E,S as s,b as i}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"对手论证","description":"","frontmatter":{"title":"对手论证","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/adversary-argument.md","filePath":"cs/adversary-argument.md","lastUpdated":1791063341000}'),p={name:"cs/adversary-argument.md"};function c(m,a,h,u,g,_){const r=B("Mermaid");return l(),d("div",null,[a[2]||(a[2]=n('<h1 id="对手论证" tabindex="-1">对手论证 <a class="header-anchor" href="#对手论证" aria-label="Permalink to &quot;对手论证&quot;">​</a></h1><div class="epigraph"><p>下界不必列出所有输入：对手在比较时才固定答案，只要与某个尚未排除的输入一致，就逼算法问够多次。</p><footer>—— 据 Knuth TAOCP 卷 3；CLRS 第 8.1 节排序下界整理</footer></div><p>上一课<a href="/cs/sorting-networks">排序网络</a>是上界构造。比较排序 \\(\\Omega(n\\log n)\\)：决策树叶子 \\(\\ge n!\\)，\\(\\log_2(n!)=\\Omega(n\\log n)\\)。缺口是对手法：求最大与次大 \\(n+\\lceil\\log n\\rceil-2\\) 次比较等。不重写主定理。后课 word RAM 换模型。主干<a href="/cs/sort-lower-bound">排序下界</a>若已写则只补对手图像。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>算法问「\\(a_i?a_j\\)」，对手选 $\\lt $ 或 $\\gt $ 使尽可能多输入仍活。直到只剩一种序或一种最大。求最大：\\(n-1\\) 次必要（锦标赛）。次大：败给冠军的人里再赛，\\(\\lceil\\log n\\rceil-1\\)。信息论：中位数、极值都有对手或决策树界。</p><p>缺口是自适应对手，不是「最坏数组已经写好」。</p><h3 id="不是在线竞争的对手" tabindex="-1">不是在线竞争的对手 <a class="header-anchor" href="#不是在线竞争的对手" aria-label="Permalink to &quot;不是在线竞争的对手&quot;">​</a></h3><p>那里对手生成序列对付在线决策。这里对手回答比较。模型不同，精神同：延迟承诺。</p><p><span class="marginnote">CLRS 8.1 决策树。Knuth 卷 3 对手。后课 word RAM 打破比较模型。</span></p><p><span class="marginnote">直觉类比：对手像猜数字游戏里那位「怎么难受怎么答」的出题人——只要还存在一个与你目前听到的回答不矛盾的数，他就绝不认输。你被迫问的次数，就是他逼出来的下界；他不是先藏好一个数，而是边玩边保持「多种可能都还活着」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>维护尚未排除的输入集合或不变量（谁仍可能最大）。每次比较缩小，给出最少次数。与决策树高度对照。</p>',12)),(l(),t(s,null,{default:e(()=>[E(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%AF%94%E8%BE%83%20i%3Aj%22%5D%20--%3E%20ADV%5B%22%E5%AF%B9%E6%89%8B%E9%80%89%E4%BB%8D%E7%9B%B8%E5%AE%B9%E7%9A%84%E7%AD%94%E6%A1%88%22%5D%0A%20%20ADV%20--%3E%20LIVE%5B%22%E6%B4%BB%E8%BE%93%E5%85%A5%E9%9B%86%E5%90%88%22%5D%0A%20%20LIVE%20--%3E%20LB%5B%22%E6%AC%A1%E6%95%B0%E4%B8%8B%E7%95%8C%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("p",null,"线性时间排序靠非比较模型（桶、基数）。",-1)),a[4]||(a[4]=i("p",null,"方法一节的图回答「对手论证的一般循环」，下面这张回答另一个具体问题：求最大与次大，那 \\(n+\\lceil\\log n\\rceil-2\\) 次比较花在哪里。",-1)),(l(),t(s,null,{default:e(()=>[E(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22n%20%E4%B8%AA%E5%80%99%E9%80%89%22%5D%20--%3E%20T%5B%22%E9%94%A6%E6%A0%87%E8%B5%9B%3A%20%E4%B8%A4%E4%B8%A4%E6%AF%94%2C%20%E8%83%9C%E8%80%85%E6%99%8B%E7%BA%A7%22%5D%0A%20%20T%20--%3E%20W%5B%22%E5%86%A0%E5%86%9B%3A%20%E5%85%B1%E8%B5%A2%20n-1%20%E5%9C%BA%22%5D%0A%20%20T%20--%3E%20L%5B%22%E7%9B%B4%E6%8E%A5%E8%B4%A5%E7%BB%99%E5%86%A0%E5%86%9B%E7%9A%84%E9%9B%86%E5%90%88%22%5D%0A%20%20L%20--%3E%20L2%5B%22%E5%85%B1%20ceil(log2%20n)%20%E4%BA%BA%2C%20%E6%AF%8F%E4%BA%BA%E6%81%B0%E8%B4%A5%E4%B8%80%E5%9C%BA%22%5D%0A%20%20L2%20--%3E%20R%5B%22%E8%B4%A5%E8%80%85%E5%86%85%E9%83%A8%E5%86%8D%E8%B5%9B%22%5D%0A%20%20R%20--%3E%20S%5B%22%E6%AC%A1%E5%A4%A7%3A%20%E5%86%8D%E6%AF%94%20ceil(log2%20n)%20-%201%20%E5%9C%BA%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">数字实例：\\(n=8\\) 时——冠军赛 \\(8-1=7\\) 场；冠军一路打了 \\(\\log_2 8=3\\) 场，所以次大只能在直接输给他的那 3 人里，再赛 \\(3-1=2\\) 场。合计 \\(7+2=9=8+\\lceil\\log_2 8\\rceil-2\\) 场，正好对上公式。</span></p><p><span class="marginnote">常见误区：初学者容易以为下界证明要穷举所有输入，实际上对手只需让每次回答至少与一个未被排除的输入相容；也容易把这里的「回答比较的对手」与在线算法里「预先生成序列的对手」混为一谈——前者卡比较次数，后者卡竞争比，共享的只是「延迟承诺」这个精神。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>活集合大小每问最多减半（平衡时），故 \\(\\log\\)；排序活集合 \\(n!\\)。对手可不平衡提问，下界仍至少最坏路径。与 Karger 对手无关。与分页对手是在线。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写代数判定树全文。不写元素唯一性 \\(\\Omega(n\\log n)\\)。后课默认：比较模型下界用决策树或对手。下一课 word RAM 与位并行。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对手延迟固定输入，逼出比较次数。</li><li>排序 \\(\\Omega(n\\log n)\\)；最大 \\(n-1\\)。</li><li>与在线对手模型不同。</li><li>出处：Knuth TAOCP 卷 3；CLRS 第 8.1 节。</li></ul>',8))])}const T=A(p,[["render",c]]);export{D as __pageData,T as default};
